<script setup lang="ts">
import{ref}from'vue';import{onPullDownRefresh,onShow}from'@dcloudio/uni-app';import WareState from'@/shared/components/WareState.vue';import{accessControlApi,type SystemAccount,type Role}from'@/features/access-control/api/access-control.api'
const loading=ref(true),error=ref(''),keyword=ref(''),accounts=ref<SystemAccount[]>([]),roles=ref<Role[]>([]),editing=ref(false),saving=ref(false);const form=ref<any>({id:0,loginName:'',displayName:'',phone:'',password:'123456',roleId:0,warehouseId:1,warehouseName:'梦花仓',status:1});
async function load(){loading.value=true;error.value='';try{[accounts.value,roles.value]=await Promise.all([accessControlApi.accounts(keyword.value),accessControlApi.accountRoles()])}catch(e){error.value=e instanceof Error?e.message:'账户加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}
function add(){form.value={id:0,loginName:'',displayName:'',phone:'',password:'123456',roleId:roles.value[0]?.id||0,warehouseId:1,warehouseName:'梦花仓',status:1};editing.value=true}function edit(x:SystemAccount){form.value={id:x.id,loginName:x.login_name,displayName:x.display_name,phone:x.phone,roleId:x.role_id,warehouseId:x.warehouse_id,warehouseName:x.warehouse_name,status:x.status};editing.value=true}
async function save(){if(saving.value)return;saving.value=true;try{form.value.id?await accessControlApi.updateAccount(form.value.id,form.value):await accessControlApi.createAccount(form.value);editing.value=false;uni.showToast({title:'账户已保存',icon:'success'});load()}catch(e){uni.showToast({title:e instanceof Error?e.message:'保存失败',icon:'none'})}finally{saving.value=false}}
function reset(){uni.showModal({title:'重置密码',editable:true,placeholderText:'请输入至少6位新密码',success:async r=>{if(r.confirm&&r.content){try{await accessControlApi.resetPassword(form.value.id,r.content);uni.showToast({title:'密码已重置',icon:'success'})}catch(e){uni.showToast({title:e instanceof Error?e.message:'重置失败',icon:'none'})}}}})}
function selectStatus(event: Event){const detail=(event as unknown as {detail:{value:boolean}}).detail;form.value.status=detail.value?1:0}
function selectRole(event: {detail: {value: string}}){form.value.roleId=roles.value[Number(event.detail.value)]?.id||0}
onShow(load);onPullDownRefresh(load)
</script>
<template><view class="page"><view class="toolbar"><view class="search"><text>⌕</text><input v-model="keyword" placeholder="姓名、账号或手机号" confirm-type="search" @confirm="load"/></view><button @click="add">新增账户</button></view><WareState v-if="loading" type="loading" title="正在加载系统账户"/><WareState v-else-if="error" type="error" title="加载失败" :description="error" action-label="重试" @action="load"/><WareState v-else-if="!accounts.length" type="empty" title="暂无系统账户"/><view v-else class="list"><view v-for="x in accounts" :key="x.id" class="card" @click="edit(x)"><view><b>{{x.display_name}}</b><span :class="{off:!x.status}">{{x.status?'正常':'停用'}}</span></view><text>{{x.login_name}} · {{x.phone||'未填手机号'}}</text><small>{{x.role_name}}　{{x.warehouse_name}}　上次登录 {{x.last_login_time||'—'}}</small></view></view><view v-if="editing" class="mask" @click="editing=false"><view class="drawer" @click.stop><view class="handle"/><view class="drawer-head"><b>{{form.id?'编辑账户':'新增账户'}}</b><text @click="editing=false">关闭</text></view><label>登录账号<input v-model="form.loginName" :disabled="!!form.id" placeholder="请输入登录账号"/></label><label>姓名<input v-model="form.displayName" placeholder="请输入姓名"/></label><label>手机号<input v-model="form.phone" type="number" placeholder="请输入手机号"/></label><label v-if="!form.id">初始密码<input v-model="form.password" password placeholder="至少6位"/></label><label>角色<picker :range="roles" range-key="name" @change="selectRole"><view class="picker">{{roles.find(x=>x.id===form.roleId)?.name||'请选择角色'}}<text>›</text></view></picker></label><view v-if="form.id" class="status"><text>账户状态</text><switch :checked="form.status===1" color="#0f766e" @change="selectStatus"/></view><button v-if="form.id" class="outline" @click="reset">重置密码</button><button class="primary" :disabled="saving" @click="save">{{saving?'保存中…':'保存账户'}}</button></view></view></view></template>
<style scoped>.page{min-height:100vh;padding:20rpx 22rpx;background:var(--wms-surface-page)}.toolbar{display:grid;grid-template-columns:1fr 150rpx;gap:12rpx}.search{display:flex;height:68rpx;align-items:center;padding:0 16rpx;border:1rpx solid var(--wms-border);border-radius:10rpx;background:#fff}.search input{min-width:0;flex:1;margin-left:7rpx;font-size:22rpx}.toolbar button{height:68rpx;margin:0;border-radius:10rpx;background:var(--wms-primary-700);color:#fff;font-size:22rpx;line-height:68rpx}.list{display:flex;flex-direction:column;gap:12rpx;margin-top:18rpx}.card{padding:19rpx 20rpx;border:1rpx solid var(--wms-border);border-radius:12rpx;background:#fff}.card>view{display:flex;align-items:center;justify-content:space-between}.card b{font-size:25rpx}.card span{padding:4rpx 10rpx;border-radius:7rpx;background:var(--wms-surface-soft);color:var(--wms-success);font-size:18rpx}.card span.off{background:#f1f2f2;color:var(--wms-text-secondary)}.card text,.card small{display:block;margin-top:8rpx;font-size:21rpx}.card small{color:var(--wms-text-secondary);font-size:18rpx}.mask{position:fixed;z-index:50;inset:0;display:flex;align-items:flex-end;background:rgba(20,38,36,.45)}.drawer{box-sizing:border-box;width:100%;max-height:90vh;overflow:auto;padding:15rpx 26rpx 28rpx;border-radius:28rpx 28rpx 0 0;background:#fff}.handle{width:68rpx;height:7rpx;margin:0 auto 20rpx;border-radius:8rpx;background:var(--wms-border)}.drawer-head,.status{display:flex;align-items:center;justify-content:space-between}.drawer-head b{font-size:29rpx}.drawer-head text{color:var(--wms-primary-700);font-size:21rpx}label{display:block;margin-top:20rpx;font-size:21rpx;font-weight:650}label input,.picker{box-sizing:border-box;width:100%;height:72rpx;margin-top:9rpx;padding:0 18rpx;border:1rpx solid var(--wms-border);border-radius:10rpx;background:#fff;font-size:22rpx}.picker{display:flex;align-items:center;justify-content:space-between}.status{margin-top:22rpx}.primary,.outline{height:76rpx;margin-top:22rpx;border-radius:10rpx;font-size:24rpx;line-height:76rpx}.primary{background:var(--wms-primary-700);color:#fff}.outline{border:1rpx solid var(--wms-primary-700);background:#fff;color:var(--wms-primary-700)}</style>
